mapper.select:
select comment.*, film.name as filmName, CASE WHEN comment.issuer_type = 'USER' THEN user.name WHEN comment.issuer_type = 'ADMIN' THEN admin.name ELSE null END as issuerName from comment left join film on comment.film_id = film.id left join user on comment.issuer_id = user.id AND comment.issuer_type = user.role left join admin on comment.issuer_id = admin.id AND comment.issuer_type = admin.role
and film.name like concat('%', #{filmName}, '%') and comment.issuer_id = #{issuerId} AND comment.issuer_type = #{issuerType} and comment.type = #{type} and comment.film_id = #{filmId}
order by comment.id desc
